describe('Notification Preferences Management', () => {
    beforeEach(() => {
        cy.visit('/settings/notifications');
        cy.login('testuser', 'password'); // Assuming a login function is available
    });

    it('should successfully update notification preferences', () => {
        cy.get('input[name="emailNotifications"]').check();
        cy.get('input[name="smsNotifications"]').uncheck();
        cy.get('button[type="submit"]').click();

        cy.get('.notification-success').should('be.visible').and('contain', 'Preferences updated successfully');
        cy.get('input[name="emailNotifications"]').should('be.checked');
        cy.get('input[name="smsNotifications"]').should('not.be.checked');
    });

    it('should show an error message when trying to save invalid preferences', () => {
        cy.get('input[name="emailNotifications"]').check();
        cy.get('input[name="smsNotifications"]').uncheck();
        cy.get('input[name="emailNotifications"]').clear(); // Assuming this field is required
        cy.get('button[type="submit"]').click();

        cy.get('.notification-error').should('be.visible').and('contain', 'Email notifications are required');
    });
});
